//! Helpers shared by korek's generators: doc comments from [`Attrs`],
//! identifier escaping, and the warning for rules a target cannot express.

use core::fmt::Write as _;

use korek_ir::codes;
use korek_ir::{Attrs, Diagnostic, Format, Rule};

/// The header line for generated files.
pub const GENERATED: &str = "Generated by korek from the schema. Do not edit.";

/// The doc text of an item: `doc`, then `description`, then unit,
/// deprecation and `since` notes. `None` when there is nothing.
pub fn doc_text(attrs: &Attrs) -> Option<String> {
    let mut parts: Vec<String> = Vec::new();
    if let Some(d) = &attrs.doc {
        parts.push(d.clone());
    }
    if let Some(d) = &attrs.description {
        parts.push(d.trim_end().to_owned());
    }
    let mut notes = Vec::new();
    if let Some(u) = &attrs.unit {
        notes.push(format!("Unit: {u}."));
    }
    if let Some(s) = &attrs.since {
        notes.push(format!("Since {s}."));
    }
    if !attrs.aliases.is_empty() {
        notes.push(format!("Also known as: {}.", attrs.aliases.join(", ")));
    }
    if !notes.is_empty() {
        parts.push(notes.join(" "));
    }
    (!parts.is_empty()).then(|| parts.join("\n\n"))
}

/// Writes `text` as comment lines (`/// `, `// `), `indent`ed.
pub fn comment(out: &mut String, indent: &str, prefix: &str, text: Option<&str>) {
    let Some(text) = text else { return };
    for line in text.lines() {
        out.push_str(indent);
        if line.is_empty() {
            out.push_str(prefix.trim_end());
        } else {
            out.push_str(prefix);
            out.push_str(line);
        }
        out.push('\n');
    }
}

/// Writes a `JSDoc` block from lines (`/** one */` when it is one line).
pub fn jsdoc(out: &mut String, indent: &str, lines: &[String]) {
    let lines: Vec<String> = lines
        .iter()
        .flat_map(|l| {
            l.lines()
                .map(|x| x.replace("*/", "*\\/"))
                .collect::<Vec<_>>()
        })
        .collect();
    match lines.as_slice() {
        [] => {}
        [one] => {
            let _ = writeln!(out, "{indent}/** {one} */");
        }
        many => {
            let _ = writeln!(out, "{indent}/**");
            for l in many {
                if l.is_empty() {
                    let _ = writeln!(out, "{indent} *");
                } else {
                    let _ = writeln!(out, "{indent} * {l}");
                }
            }
            let _ = writeln!(out, "{indent} */");
        }
    }
}

/// `JSDoc` lines for an item: doc text, `@deprecated`, `@example`s, plus
/// `extra` tags.
pub fn jsdoc_lines(attrs: &Attrs, extra: &[String]) -> Vec<String> {
    let mut v = Vec::new();
    if let Some(t) = doc_text(attrs) {
        v.push(t);
    }
    if let Some(d) = &attrs.deprecated {
        v.push(if d.is_empty() {
            "@deprecated".into()
        } else {
            format!("@deprecated {d}")
        });
    }
    for e in &attrs.examples {
        v.push(format!("@example {e}"));
    }
    v.extend(extra.iter().cloned());
    v
}

/// A TypeScript property name: bare when an identifier, else quoted.
pub fn ts_prop(name: &str) -> String {
    let ident = name
        .chars()
        .next()
        .is_some_and(|c| c.is_ascii_alphabetic() || c == '_' || c == '$')
        && name
            .chars()
            .all(|c| c.is_ascii_alphanumeric() || c == '_' || c == '$');
    if ident {
        name.to_owned()
    } else {
        format!("{name:?}")
    }
}

const RUST_KEYWORDS: &[&str] = &[
    "as", "async", "await", "break", "const", "continue", "dyn", "else", "enum", "extern", "false",
    "fn", "for", "gen", "if", "impl", "in", "let", "loop", "match", "mod", "move", "mut", "pub",
    "ref", "return", "static", "struct", "trait", "true", "type", "unsafe", "use", "where",
    "while", "abstract", "become", "box", "do", "final", "macro", "override", "priv", "try",
    "typeof", "unsized", "virtual", "yield",
];

/// A Rust identifier, raw (`r#type`) when it is a keyword.
pub fn rust_ident(name: &str) -> String {
    if RUST_KEYWORDS.contains(&name) {
        format!("r#{name}")
    } else {
        name.to_owned()
    }
}

/// The warning for a rule `target` cannot express (an error with
/// `--strict`, which the driver applies).
pub fn unsupported(plugin: &str, rule: &Rule, why: &str) -> Diagnostic {
    Diagnostic::warning(
        codes::RULE_UNSUPPORTED,
        format!(
            "korek-gen-{plugin} cannot express `{}`: {why}",
            rule.kind.name()
        ),
    )
    .at(rule.span, "not enforced by this target")
}

/// A JSON value as a JS/TS literal (JSON is valid TS).
pub fn js(v: &serde_json::Value) -> String {
    v.to_string()
}

/// Regular expressions (valid in RE2 and ECMAScript) for formats that some
/// targets have no native check for.
pub fn format_regex(f: Format) -> Option<&'static str> {
    Some(match f {
        Format::Cuid => r"^c[^\s-]{8,}$",
        Format::Cuid2 => "^[0-9a-z]+$",
        Format::Nanoid => "^[a-zA-Z0-9_-]{21}$",
        Format::Date => r"^\d{4}-(0[1-9]|1[0-2])-(0[1-9]|[12]\d|3[01])$",
        Format::Time => r"^([01]\d|2[0-3]):[0-5]\d(:[0-5]\d(\.\d+)?)?$",
        Format::Datetime => {
            r"^\d{4}-\d{2}-\d{2}[Tt]\d{2}:\d{2}:\d{2}(\.\d+)?([Zz]|[+-]\d{2}:\d{2})$"
        }
        Format::Duration => r"^P(\d+W|(\d+Y)?(\d+M)?(\d+D)?(T(\d+H)?(\d+M)?(\d+(\.\d+)?S)?)?)$",
        Format::Base64 => "^([A-Za-z0-9+/]{4})*([A-Za-z0-9+/]{2}==|[A-Za-z0-9+/]{3}=)?$",
        Format::Base64url => "^[A-Za-z0-9_-]*$",
        Format::Jwt => r"^[A-Za-z0-9_-]+\.[A-Za-z0-9_-]+\.[A-Za-z0-9_-]*$",
        Format::E164 => r"^\+[1-9]\d{6,14}$",
        Format::Lowercase => "^[^A-Z]*$",
        Format::Uppercase => "^[^a-z]*$",
        _ => return None,
    })
}
